#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "heat-3d.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		 DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int i, j, k;

  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++)
        A[i][j][k] = B[i][j][k] = (DATA_TYPE) (i + j + (n-k))* 10 / (n);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;
  int ii, jj, kk;

  /* Create local restrict-qualified aliases to help the compiler's
     alias analysis.  The arrays A and B are distinct in this benchmark,
     so it is safe to declare them as non-overlapping here. */
  DATA_TYPE (*restrict A_)[n][n] = A;
  DATA_TYPE (*restrict B_)[n][n] = B;

  /* Stencil weights (algebraically equivalent to the original formula):
       B_ijk = 0.25 * A_ijk + 0.125 * sum(neighbors of A_ijk)
     and likewise for the B→A sweep.  This reduces the number of
     multiplications while preserving the mathematical stencil. */
  const DATA_TYPE w_center   = SCALAR_VAL(0.25);
  const DATA_TYPE w_neighbor = SCALAR_VAL(0.125);

  /* Interior region (Dirichlet boundaries at {0, n-1} in each dimension
     are never updated). We keep this in variables so the compiler can
     propagate them easily and so that the tiling code is clearer. */
  const int i_start = 1;
  const int i_end   = _PB_N - 1; /* exclusive upper bound */
  const int j_start = 1;
  const int j_end   = _PB_N - 1;
  const int k_start = 1;
  const int k_end   = _PB_N - 1;

  /* Simple 3D spatial tiling to improve data locality.
     - TI, TJ: relatively small so that a tile in (i,j) along with its
       k-line fits comfortably in cache.
     - TK: larger to keep long unit-stride runs along k for good SIMD
       vectorization and prefetching.

     These values are chosen generically for modern x64 CPUs; they work
     for all N because the edge tiles are handled with min() bounds. */
  const int TI = 16;
  const int TJ = 8;
  const int TK = 64;

#pragma scop
  /* Time loop remains sequential; each iteration performs two 3D sweeps:
       1) B <- stencil(A)
       2) A <- stencil(B)
     as in the original kernel. */
  for (t = 0; t < tsteps; ++t) {

    /* ------------------------------------------------------------------
     * Phase 1: update B from A (A → B sweep)
     * ------------------------------------------------------------------ */
    for (ii = i_start; ii < i_end; ii += TI) {
      const int i_max = (ii + TI < i_end) ? (ii + TI) : i_end;

      for (jj = j_start; jj < j_end; jj += TJ) {
        const int j_max = (jj + TJ < j_end) ? (jj + TJ) : j_end;

        for (kk = k_start; kk < k_end; kk += TK) {
          const int k_max = (kk + TK < k_end) ? (kk + TK) : k_end;

          for (i = ii; i < i_max; ++i) {
            for (j = jj; j < j_max; ++j) {
              /* Innermost loop has unit-stride accesses in memory,
                 which is ideal for the compiler's auto-vectorizer. */
              for (k = kk; k < k_max; ++k) {
                const DATA_TYPE center =
                    A_[i][j][k];

                const DATA_TYPE neighbors =
                    A_[i+1][j  ][k  ] + A_[i-1][j  ][k  ] +
                    A_[i  ][j+1][k  ] + A_[i  ][j-1][k  ] +
                    A_[i  ][j  ][k+1] + A_[i  ][j  ][k-1];

                B_[i][j][k] =
                    w_center   * center +
                    w_neighbor * neighbors;
              }
            }
          }
        }
      }
    }

    /* ------------------------------------------------------------------
     * Phase 2: update A from B (B → A sweep)
     * ------------------------------------------------------------------ */
    for (ii = i_start; ii < i_end; ii += TI) {
      const int i_max = (ii + TI < i_end) ? (ii + TI) : i_end;

      for (jj = j_start; jj < j_end; jj += TJ) {
        const int j_max = (jj + TJ < j_end) ? (jj + TJ) : j_end;

        for (kk = k_start; kk < k_end; kk += TK) {
          const int k_max = (kk + TK < k_end) ? (kk + TK) : k_end;

          for (i = ii; i < i_max; ++i) {
            for (j = jj; j < j_max; ++j) {
              for (k = kk; k < k_max; ++k) {
                const DATA_TYPE center =
                    B_[i][j][k];

                const DATA_TYPE neighbors =
                    B_[i+1][j  ][k  ] + B_[i-1][j  ][k  ] +
                    B_[i  ][j+1][k  ] + B_[i  ][j-1][k  ] +
                    B_[i  ][j  ][k+1] + B_[i  ][j  ][k-1];

                A_[i][j][k] =
                    w_center   * center +
                    w_neighbor * neighbors;
              }
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
