  int ii, jj, kk;

  /* Precompute stencil coefficients.
   *
   * Original update (per dimension):
   *   0.125 * (x_{+1} - 2*x_0 + x_{-1})
   *
   * Summed over three dimensions and adding the center:
   *   new = A_0
   *         + 0.125 * [ (A_{i+1} - 2*A_0 + A_{i-1})
   *                    + (A_{j+1} - 2*A_0 + A_{j-1})
   *                    + (A_{k+1} - 2*A_0 + A_{k-1}) ]
   *       = 0.25 * A_0 + 0.125 * (sum of 6 neighbors of A_0)
   *
   * We use the equivalent form:
   *   new = w_center * center + w_neighbor * neighbor_sum
   * which reduces the number of multiplications and improves
   * vectorization opportunities while preserving the stencil.
   */
  const DATA_TYPE w_center   = SCALAR_VAL(0.25);
  const DATA_TYPE w_neighbor = SCALAR_VAL(0.125);

  /* Tunable spatial tile sizes (chosen for good cache locality on
   * modern x86-64; they can be adjusted if desired).
   * We tile all three spatial dimensions but keep k as the innermost,
   * unit-stride loop for efficient SIMD.
   */
  const int ti = 16;
  const int tj = 16;
  const int tk = 32;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* -----------------------------
     * Phase 1: B := stencil(A)
     * -----------------------------
     * Reads only from A and writes to B; interior (i,j,k) points are
     * mutually independent, so we can safely reorder them via tiling.
     */
    for (ii = 1; ii < _PB_N-1; ii += ti) {
      int i_end = ii + ti;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

      for (jj = 1; jj < _PB_N-1; jj += tj) {
        int j_end = jj + tj;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

        for (kk = 1; kk < _PB_N-1; kk += tk) {
          int k_end = kk + tk;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {
              /* Innermost k-loop has unit-stride accesses to A and B,
               * ideal for vectorization. The ivdep pragma tells GCC
               * that there are no loop-carried dependencies along k.
               */
#pragma GCC ivdep
              for (k = kk; k < k_end; k++) {
                DATA_TYPE center = A[i][j][k];

                DATA_TYPE neighbor_sum =
                  A[i-1][j][k] + A[i+1][j][k] +
                  A[i][j-1][k] + A[i][j+1][k] +
                  A[i][j][k-1] + A[i][j][k+1];

                B[i][j][k] = w_center * center +
                             w_neighbor * neighbor_sum;
              }
            }
          }
        }
      }
    }

    /* -----------------------------
     * Phase 2: A := stencil(B)
     * -----------------------------
     * Same stencil, now reading from B and writing back to A.
     * This entire phase is executed after Phase 1 for each t,
     * matching the original sequential dependence structure.
     */
    for (ii = 1; ii < _PB_N-1; ii += ti) {
      int i_end = ii + ti;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

      for (jj = 1; jj < _PB_N-1; jj += tj) {
        int j_end = jj + tj;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

        for (kk = 1; kk < _PB_N-1; kk += tk) {
          int k_end = kk + tk;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {
#pragma GCC ivdep
              for (k = kk; k < k_end; k++) {
                DATA_TYPE center = B[i][j][k];

                DATA_TYPE neighbor_sum =
                  B[i-1][j][k] + B[i+1][j][k] +
                  B[i][j-1][k] + B[i][j+1][k] +
                  B[i][j][k-1] + B[i][j][k+1];

                A[i][j][k] = w_center * center +
                             w_neighbor * neighbor_sum;
              }
            }
          }
        }
      }
    }
  }
#pragma endscop

}


