      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving the original numerical formula):
   - 3D spatial blocking (tiling) in (i, j, k) to improve cache locality.
   - Use of restrict-qualified local pointers to A and B to improve
     alias analysis and enable better auto-vectorization.
   - Hoisting of scalar constants (0.125 and 2.0) out of the loops.
   - Inner-loop vectorization friendliness: k remains the innermost
     dimension (unit-stride), with GCC unroll and ivdep hints.
   - The arithmetic expression for the stencil is kept in the same
     algebraic form as the original code to avoid changing floating-
     point semantics beyond what the compiler already does.
 */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Local restrict-qualified views of the 3D arrays.
     This tells the compiler that A_ and B_ do not alias, which
     helps vectorization and scheduling. */
  DATA_TYPE (*restrict A_)[n][n] = A;
  DATA_TYPE (*restrict B_)[n][n] = B;

  /* Stencil constants, hoisted out of all loops. */
  const DATA_TYPE c0 = SCALAR_VAL(0.125);
  const DATA_TYPE c2 = SCALAR_VAL(2.0);

  /* Spatial tiling sizes.
     Chosen so that a 3D tile of A and B (plus neighbor planes) fits
     comfortably into the cache on typical x64 CPUs. These can be
     tuned further if desired. */
  const int TI = 8;
  const int TJ = 8;
  const int TK = 32;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* ------------------------------------------------------------
     * Phase 1: update B from A (matches first triple loop exactly)
     * ------------------------------------------------------------ */
    for (int ii = 1; ii < _PB_N-1; ii += TI) {
      int i_end = ii + TI;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

      for (int jj = 1; jj < _PB_N-1; jj += TJ) {
        int j_end = jj + TJ;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

        for (int kk = 1; kk < _PB_N-1; kk += TK) {
          int k_end = kk + TK;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {

              /* k is the innermost, unit-stride loop.  These pragmas
                 give the compiler additional freedom to vectorize and
                 unroll without worrying about false dependencies. */
#pragma GCC ivdep
#pragma GCC unroll 4
              for (k = kk; k < k_end; k++) {
                DATA_TYPE aijk = A_[i][j][k];

                /* Keep the arithmetic in the same algebraic form as
                   the original code: three directional second-
                   derivative terms scaled by 0.125, plus the center. */
                B_[i][j][k] =
                    c0 * (A_[i+1][j][k] - c2 * aijk + A_[i-1][j][k])
                  + c0 * (A_[i][j+1][k] - c2 * aijk + A_[i][j-1][k])
                  + c0 * (A_[i][j][k+1] - c2 * aijk + A_[i][j][k-1])
                  + aijk;
              }
            }
          }
        }
      }
    }

    /* ------------------------------------------------------------
     * Phase 2: update A from B (matches second triple loop exactly)
     * ------------------------------------------------------------ */
    for (int ii = 1; ii < _PB_N-1; ii += TI) {
      int i_end = ii + TI;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

      for (int jj = 1; jj < _PB_N-1; jj += TJ) {
        int j_end = jj + TJ;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

      for (int kk = 1; kk < _PB_N-1; kk += TK) {
          int k_end = kk + TK;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {

#pragma GCC ivdep
#pragma GCC unroll 4
              for (k = kk; k < k_end; k++) {
                DATA_TYPE bijk = B_[i][j][k];

                A_[i][j][k] =
                    c0 * (B_[i+1][j][k] - c2 * bijk + B_[i-1][j][k])
                  + c0 * (B_[i][j+1][k] - c2 * bijk + B_[i][j-1][k])
                  + c0 * (B_[i][j][k+1] - c2 * bijk + B_[i][j][k-1])
                  + bijk;
              }
            }
          }
        }
      }
    }
  }
#pragma endscop

}


