/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n))

{
  int i, j, k;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("A");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      for (k = 0; k < n; k++) {
         if ((i * n * n + j * n + k) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
         fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, A[i][j][k]);
      }
  POLYBENCH_DUMP_END("A");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Create restrict-qualified local aliases to help the compiler with
   * alias analysis and vectorization.  A and B never alias in this
   * benchmark (they are separate allocations). */
  DATA_TYPE (*restrict A_)[n][n] = A;
  DATA_TYPE (*restrict B_)[n][n] = B;

  /* Hoist scalar constants out of the loops. */
  const DATA_TYPE c_neigh  = SCALAR_VAL(0.125); /* 0.125 */
  const DATA_TYPE c_six    = SCALAR_VAL(6.0);   /* 6.0   */

  /* Cache/block sizes for the spatial dimensions.
   * These are chosen to give reasonable cache locality on typical
   * PolyBench sizes while still being generic.
   * They do not need to divide (_PB_N-2) evenly; edge tiles are handled
   * by min() logic below. */
  const int TI = 16;
  const int TJ = 16;
  const int TK = 32;

#pragma scop
  /* Time loop remains purely sequential to respect the physical time
   * stepping. Inside each time step, two Jacobi-like sweeps are
   * performed:
   *   1) B = stencil(A)
   *   2) A = stencil(B)
   */
  for (t = 1; t <= TSTEPS; t++) {

    /* -----------------------------
     * Phase 1: update B from A
     * -----------------------------
     * Original expression (per grid point):
     *
     *   B = 0.125*(A[i+1][j][k] - 2*A[i][j][k] + A[i-1][j][k])
     *     + 0.125*(A[i][j+1][k] - 2*A[i][j][k] + A[i][j-1][k])
     *     + 0.125*(A[i][j][k+1] - 2*A[i][j][k] + A[i][j][k-1])
     *     + A[i][j][k];
     *
     * Algebraically this is:
     *
     *   center = A[i][j][k];
     *   lap    = sum(6 neighbors of center) - 6*center;
     *   B      = center + 0.125 * lap;
     *
     * which we use below. This reduces redundant multiplications and
     * lets the compiler generate efficient code while remaining
     * mathematically equivalent to the original stencil.
     */

    for (int ii = 1; ii < _PB_N - 1; ii += TI) {
      int i_end = ii + TI;
      if (i_end > _PB_N - 1)
        i_end = _PB_N - 1;

      for (int jj = 1; jj < _PB_N - 1; jj += TJ) {
        int j_end = jj + TJ;
        if (j_end > _PB_N - 1)
          j_end = _PB_N - 1;

        for (int kk = 1; kk < _PB_N - 1; kk += TK) {
          int k_end = kk + TK;
          if (k_end > _PB_N - 1)
            k_end = _PB_N - 1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {
              /* Pointers to the current row and its six neighbors.
               * Using row pointers avoids repeated computation of
               * the 3D address inside the innermost loop. */
              DATA_TYPE *restrict Bi_j   = &B_[i][j][0];
              DATA_TYPE *restrict Ai_j   = &A_[i][j][0];
              DATA_TYPE *restrict Ai_jm1 = &A_[i][j-1][0];
              DATA_TYPE *restrict Ai_jp1 = &A_[i][j+1][0];
              DATA_TYPE *restrict Aim1_j = &A_[i-1][j][0];
              DATA_TYPE *restrict Aip1_j = &A_[i+1][j][0];

              /* k is the innermost, stride‑1 dimension: ideal for SIMD. */
#pragma GCC ivdep
              for (k = kk; k < k_end; k++) {
                const DATA_TYPE center = Ai_j[k];

                /* 7‑point Laplacian-like combination of neighbors. */
                const DATA_TYPE lap =
                    Aip1_j[k] + Aim1_j[k] +
                    Ai_jp1[k] + Ai_jm1[k] +
                    Ai_j[k+1] + Ai_j[k-1] -
                    c_six * center;

                Bi_j[k] = center + c_neigh * lap;
              }
            }
          }
        }
      }
    }

    /* -----------------------------
     * Phase 2: update A from B
     * -----------------------------
     * Same stencil, but reading B and writing A.
     */

    for (int ii = 1; ii < _PB_N - 1; ii += TI) {
      int i_end = ii + TI;
      if (i_end > _PB_N - 1)
        i_end = _PB_N - 1;

      for (int jj = 1; jj < _PB_N - 1; jj += TJ) {
        int j_end = jj + TJ;
        if (j_end > _PB_N - 1)
          j_end = _PB_N - 1;

        for (int kk = 1; kk < _PB_N - 1; kk += TK) {
          int k_end = kk + TK;
          if (k_end > _PB_N - 1)
            k_end = _PB_N - 1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {
              DATA_TYPE *restrict Ai_j   = &A_[i][j][0];
              DATA_TYPE *restrict Bi_j   = &B_[i][j][0];
              DATA_TYPE *restrict Bi_jm1 = &B_[i][j-1][0];
              DATA_TYPE *restrict Bi_jp1 = &B_[i][j+1][0];
              DATA_TYPE *restrict Bim1_j = &B_[i-1][j][0];
              DATA_TYPE *restrict Bip1_j = &B_[i+1][j][0];

#pragma GCC ivdep
              for (k = kk; k < k_end; k++) {
                const DATA_TYPE center = Bi_j[k];

                const DATA_TYPE lap =
                    Bip1_j[k] + Bim1_j[k] +
                    Bi_jp1[k] + Bi_jm1[k] +
                    Bi_j[k+1] + Bi_j[k-1] -
                    c_six * center;

                Ai_j[k] = center + c_neigh * lap;
              }
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_3D_ARRAY_DECL(A, DATA_TYPE, N, N, N, n, n, n);
  POLYBENCH_3D_ARRAY_DECL(B, DATA_TYPE, N, N, N, n, n, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_heat_3d (tsteps, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
