void kernel_heat_3d[[gnu::flatten, gnu::noinline]](int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

  /* Stencil coefficients, algebraically equivalent to the original form.
   *
   * Original update for B:
   *   B = 0.125*(A_{i+1} - 2*A + A_{i-1})
   *     + 0.125*(A_{j+1} - 2*A + A_{j-1})
   *     + 0.125*(A_{k+1} - 2*A + A_{k-1})
   *     + A
   *
   * This simplifies to:
   *   B = 0.125 * (sum_of_6_neighbors) + 0.25 * A
   *
   * We use the simplified coefficients (same stencil operator up to
   * floating-point associativity) to reduce multiplications.
   */
  const DATA_TYPE w_neighbor = SCALAR_VAL(0.125); /* weight of each neighbor */
  const DATA_TYPE w_center   = SCALAR_VAL(0.25);  /* weight of center point  */

  /* Spatial tile sizes.
   * These are chosen to keep a 3D tile of A and B (plus halos) in cache,
   * improving temporal and spatial locality. They can be tuned per target. */
  const int tile_i = 16;
  const int tile_j = 8;
  const int tile_k = 32;

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {

    /* ------------------------------------------------------------------ */
    /* Phase 1: update B from A on interior points (Dirichlet boundaries
     *          on the outermost planes are left unchanged).
     *
     * We apply 3D tiling in (i,j,k) to improve cache locality while
     * preserving the original data dependences:
     *   - Within this phase, all points are independent because only A
     *     is read and only B is written.
     *   - Across phases and time steps, the order is unchanged:
     *       A -> B (this phase), then B -> A (next phase).
     * ------------------------------------------------------------------ */
    for (int ii = 1; ii < _PB_N-1; ii += tile_i) {
      int i_end = ii + tile_i;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

      for (int jj = 1; jj < _PB_N-1; jj += tile_j) {
        int j_end = jj + tile_j;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

        for (int kk = 1; kk < _PB_N-1; kk += tile_k) {
          int k_end = kk + tile_k;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

          for (i = ii; i < i_end; i++) {
            for (j = jj; j < j_end; j++) {
              for (k = kk; k < k_end; k++) {
                /* Load center once and reuse; neighbors are read-only. */
                DATA_TYPE center = A[i][j][k];

                DATA_TYPE neighbor_sum =
                    A[i+1][j  ][k  ] + A[i-1][j  ][k  ] +
                    A[i  ][j+1][k  ] + A[i  ][j-1][k  ] +
                    A[i  ][j  ][k+1] + A[i  ][j  ][k-1];

                B[i][j][k] = w_center * center +
                             w_neighbor * neighbor_sum;
              }
            }
          }
        }
      }
    }

