    /* Phase 2: update A from B on interior points, using the same stencil
     * and tiling strategy. All updates within this phase are independent
     * (read-only from B, write-only to A), and the phase starts only
     * after Phase 1 is fully completed, as in the original code.
     * ------------------------------------------------------------------ */
    for (int ii = 1; ii < _PB_N-1; ii += tile_i) {
      int i_end = ii + tile_i;
      if (i_end > _PB_N-1)
        i_end = _PB_N-1;

