        int j_end = jj + tile_j;
        if (j_end > _PB_N-1)
          j_end = _PB_N-1;

        for (int kk = 1; kk < _PB_N-1; kk += tile_k) {
          int k_end = kk + tile_k;
          if (k_end > _PB_N-1)
            k_end = _PB_N-1;

