            for (j = jj; j < j_end; j++) {
              for (k = kk; k < k_end; k++) {
                DATA_TYPE center = B[i][j][k];

                DATA_TYPE neighbor_sum =
                    B[i+1][j  ][k  ] + B[i-1][j  ][k  ] +
                    B[i  ][j+1][k  ] + B[i  ][j-1][k  ] +
                    B[i  ][j  ][k+1] + B[i  ][j  ][k-1];

                A[i][j][k] = w_center * center +
                             w_neighbor * neighbor_sum;
              }
            }
          }
        }
      }
    }
  }
